\begin{figure*}[!t]
  \centering
  \includegraphics[width=164.600mm]{figures/02-foundations/01-basics/generated/meta-learning/figure.png}
  \caption{任务内适应与跨任务更新。元训练任务从共同起点$\bm\theta$出发，用任务内适应样本得到参数$\bm\theta'_{\tau}$，再汇总另一批检查样本上的损失$L_{\tau}$来更新起点；两批样本都参与元训练。未参加元训练的新任务只用少量适应样本调整参数，最终检查评分不回传共同起点。任务与图像样本为教学构造，不是Omniglot原始样本。}
  \label{fig:meta-learning-process}
\end{figure*}

\begin{figure*}[htbp]
  \centering
  \includegraphics[width=164.600mm]{figures/02-foundations/01-basics/generated/online-feedback-order/figure.png}
  \caption{在线学习先用当前模型预测并保存此时尚未看到答案的结果，反馈可以延迟或按小批次到达，随后更新只作用于后续输入。下方对照只用固定参数持续响应的实时预测；请求持续到来本身不构成在线学习。}
  \label{fig:online-feedback-order}
\end{figure*}

令本轮参与集合为$I_t$，第$i$方数据为$D_i$，$n_i=|D_i|$，则
\begin{equation}
  n=\sum_{i\in I_t}n_i,\qquad
  \bm\theta^{(t+1)}
  =\sum_{i\in I_t}\frac{n_i}{n}\bm\theta_i^{(t+1)}.
  \label{eq:fedavg-overview}
\end{equation}
$\bm\theta_i^{(t+1)}$表示从$\bm\theta^{(t)}$出发完成本地训练的参数，所以样本多的参与方获得更大权重。

\begin{figure*}[t]
  \centering
  \includegraphics[width=164.600mm]{figures/02-foundations/01-basics/generated/federated-learning/figure.png}
  \caption{中心协调式联邦学习的一轮通信。协调方向三个示意参与方下发同一组共享参数$\bm\theta^{(t)}$；各方使用边界内的本地记录集$D_i$训练，得到本地参数$\bm\theta_i^{(t+1)}$并上传。协调方按正文所述的样本量权重形成下一版本$\bm\theta^{(t+1)}$，再统一下发。记录图元与参与方数量为教学示意；原始记录留在本地，但模型更新仍可能泄露信息，联邦组织方式本身不提供隐私保证。}
  \label{fig:federated-learning-process}
\end{figure*}
